package com.fooddelivery.controller;
import com.fooddelivery.model.*; import com.fooddelivery.repository.*; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.math.BigDecimal;
@Configuration public class SeedController { @Bean CommandLineRunner seed(RestaurantRepository rr,MenuItemRepository mr,UserRepository ur,PasswordEncoder pe){return args->{if(rr.count()>0)return;var owner=new User();owner.setEmail("owner@demo.com");owner.setPassword(pe.encode("password"));owner.setFullName("Demo Owner");owner.setRole(UserRole.RESTAURANT_OWNER);ur.save(owner);var r=new Restaurant();r.setName("Spice Garden");r.setDescription("Indian comfort food and biryani");r.setAddress("Pune, Maharashtra");r.setImageUrl("https://images.unsplash.com/photo-1517248135467-4c7edcad34c4");r.setOwner(owner);rr.save(r);String[][] items={{"Chicken Biryani","Aromatic basmati biryani","299"},{"Paneer Tikka","Char-grilled paneer","229"},{"Butter Naan","Tandoor baked naan","59"},{"Masala Dosa","Crispy dosa with chutney","149"}};for(String[] x:items){var m=new MenuItem();m.setName(x[0]);m.setDescription(x[1]);m.setPrice(new BigDecimal(x[2]));m.setRestaurant(r);mr.save(m);}};} }